// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // 1. admissible domain: any uint16, no assumption needed
        address baseToken = address(0);
        address nft = address(0);
        uint128 virtualBaseTokenReserves = 0;
        uint128 virtualNftReserves = 0;
        uint56 changeFee = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        // 2. call initialize on C
        bool ok;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            _feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. assertTrue: if the call succeeded, feeRate must equal the input _feeRate
        assertTrue(
            !ok || c.feeRate() == _feeRate
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 feeRate1, uint16 feeRate2) public {
        vm.assume(feeRate1 <= 5000);
        vm.assume(feeRate2 > 5000);
        c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            feeRate1,
            bytes32(0),
            false,
            false
        );
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            feeRate2,
            bytes32(0),
            false,
            false
        ) { assertTrue(false, "re-initialization should have reverted"); } catch { }
    }
}
